<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {api,openProtected} from './api'
import QuestionContent from './QuestionContent.vue'
import PaperImageCropper from './PaperImageCropper.vue'
import {questionKinds as kinds,type ExamSource,type DraftGroup,type DraftQuestion} from './examTypes'
const props=defineProps<{courseId:number}>()
const emit=defineEmits<{assemble:[ids:number[]];changed:[];editQuestion:[id:number]}>()
const rows=ref<ExamSource[]>([]),source=ref<ExamSource|null>(null),next=ref<number|null>(null)
const file=ref<File|null>(null),key=ref(''),busy=ref(false),loading=ref(true),error=ref(''),notice=ref(''),dirty=ref(false),confirmed=ref(false),unitId=ref(1)
const uploadFiles=ref<File[]>([])
const now=ref(Date.now())
const query=ref(''),showArchived=ref(false),paperName=ref(''),selectedGroup=ref(0),selectedQuestion=ref(0),previewMode=ref(false)
const cropTarget=ref<'body'|'material'|'explanation'>('body'),replaceMarker=ref('')
const cropDestination=computed(()=>{const group=source.value?.draft.groups[selectedGroup.value];return cropTarget.value==='material'?group:group?.questions[selectedQuestion.value]})
const cropText=computed(()=>{const target=cropDestination.value;return target?String((target as unknown as Record<string,string>)[cropTarget.value]||''):''})
const cropMarkers=computed(()=>[...new Set(cropText.value.match(/\{\{asset:\d+\}\}/g)||[])])
watch([cropTarget,selectedGroup,selectedQuestion],()=>replaceMarker.value='')
const questionCount=computed(()=>source.value?.draft.groups?.reduce((n,g)=>n+g.questions.length,0)||0)
const elapsed=computed(()=>source.value?Math.max(0,Math.floor((now.value-Date.parse(source.value.created_at||new Date(now.value).toISOString()))/1000)):0)
const currentUnit=computed(()=>source.value?.units.find(u=>u.id===unitId.value))
let timer:ReturnType<typeof setInterval>|undefined
async function run(action:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(page=1){const result=await api<{items:ExamSource[];next_page:number|null}>(`courses/${props.courseId}/exam-sources/?page=${page}&q=${encodeURIComponent(query.value)}&archived=${showArchived.value?'1':'0'}`);rows.value=page===1?result.items:[...rows.value,...result.items];next.value=result.next_page}
function setSource(value:ExamSource){source.value=value;cropTarget.value='body';replaceMarker.value='';paperName.value=value.name;dirty.value=false;confirmed.value=false;selectedGroup.value=0;selectedQuestion.value=0;unitId.value=value.units[0]?.id||1}
function mayLeave(){return !dirty.value||confirm('仍有未保存的整理内容，离开会丢失这些修改。继续？')}
async function select(id:number){if(!mayLeave())return;await run(async()=>setSource(await api<ExamSource>(`exam-sources/${id}/`)))}
function closePaper(){if(mayLeave()){source.value=null;dirty.value=false;notice.value=''}}
function choose(event:Event){uploadFiles.value=Array.from((event.target as HTMLInputElement).files||[]);file.value=uploadFiles.value[0]||null;key.value=crypto.randomUUID()}
async function upload(){if(!file.value||!mayLeave())return;await run(async()=>{const form=new FormData();for(const f of uploadFiles.value)form.append('file',f);form.append('request_key',key.value);setSource(await api<ExamSource>(`courses/${props.courseId}/exam-sources/`,'POST',form));await load();notice.value='原卷已保存，后台正在整理。可以离开后再回来查看。'})}
function changed(){dirty.value=true;confirmed.value=false}
async function save(){if(!source.value||!dirty.value)return;if(source.value.status==='committed'&&!confirm('将整卷修改同步到题库。移除的题目会停用，已有答卷不变；未开始的组卷请重新核对。继续保存？'))throw new Error('尚未同步，编辑内容已保留');const result=await api<ExamSource>(`exam-sources/${source.value.id}/`,'PUT',{expected_revision:source.value.revision,draft:source.value.draft,bank_versions:source.value.bank_versions,group_versions:source.value.group_versions});source.value=result;dirty.value=false;notice.value='整理内容已保存';if(result.status==='committed')emit('changed')}
async function manage(value:'rename'|'archive'|'restore'){if(!source.value||!mayLeave())return;if(value==='archive'&&!confirm('归档这份原卷？可以在已归档列表恢复。题库题目和已有考试不会删除。'))return;await run(async()=>{setSource(await api<ExamSource>(`exam-sources/${source.value!.id}/`,'POST',{action:value,name:paperName.value,expected_revision:source.value!.revision}));await load();notice.value=value==='rename'?'名称已更新':value==='archive'?'原卷已归档，题库保留':'原卷已恢复'})}
function focusQuestion(gi:number,qi:number){selectedGroup.value=gi;selectedQuestion.value=qi;const q=source.value?.draft.groups[gi]?.questions[qi];if(q?.source_units[0])unitId.value=q.source_units[0]}
function insertCrop(marker:string){
 const target=cropDestination.value
 if(!target)return
 const field=cropTarget.value
 const value=cropText.value
 if(replaceMarker.value&&!value.includes(replaceMarker.value)){error.value='待替换配图已变化，请重新选择；新裁图尚未插入';return}
 ;(target as unknown as Record<string,string>)[field]=replaceMarker.value?value.split(replaceMarker.value).join(marker):value+'\n'+marker
 replaceMarker.value='';changed();notice.value='配图已更新到选择的位置，请预览并保存；已有测验不变'
}
async function action(value:string){if(!source.value)return;await run(async()=>{
  if(value==='commit'&&!confirmed.value)throw new Error('请先确认已核对题干、材料和配图')
  if(value==='commit')await save()
  else if(dirty.value&&!mayLeave())return
  setSource(await api<ExamSource>(`exam-sources/${source.value!.id}/`,'POST',{action:value,expected_revision:source.value!.revision,confirmed:value==='commit'}));await load()
  if(value==='commit'){notice.value='已加入题库。分值在组卷时设置；无答案键的题目由教师人工批改。';emit('changed')}
})}
function newQuestion():DraftQuestion{return {kind:'short',body:'',options:[],answer:{values:[]},explanation:'',source_units:[unitId.value]}}
function addGroup(){source.value!.draft.groups.push({title:'新题组',material:'',source_units:[unitId.value],questions:[newQuestion()]});focusQuestion(source.value!.draft.groups.length-1,0);changed()}
function addQuestion(group:DraftGroup){group.questions.push(newQuestion());selectedQuestion.value=group.questions.length-1;changed()}
function move<T>(items:T[],index:number,delta:number){const target=index+delta;if(target<0||target>=items.length)return;[items[index],items[target]]=[items[target],items[index]];changed()}
function removeQuestion(group:DraftGroup,index:number){if(!confirm('移除这道题？保存前可重新读取恢复；已入库题目会停用，历史答卷保留。'))return;group.questions.splice(index,1);selectedQuestion.value=Math.max(0,index-1);changed()}
function removeGroup(index:number){if(!confirm('移除此题组及小题？保存前可重新读取恢复；历史答卷保留。'))return;source.value!.draft.groups.splice(index,1);selectedGroup.value=Math.max(0,index-1);selectedQuestion.value=0;changed()}
function setKind(q:DraftQuestion){q.options=['single','multiple'].includes(q.kind)?['','']:[];q.answer={values:[]};changed()}
function toggleAnswer(q:DraftQuestion,index:number){const value=String(index);q.answer.values=q.kind==='single'?[value]:q.answer.values.includes(value)?q.answer.values.filter(v=>v!==value):[...q.answer.values,value];changed()}
function removeOption(q:DraftQuestion,index:number){q.options.splice(index,1);q.answer.values=q.answer.values.filter(v=>Number(v)!==index).map(v=>String(Number(v)>index?Number(v)-1:Number(v)));changed()}
async function picture(target:{material:string}|DraftQuestion,field:'material'|'body'|'explanation',event:Event){const image=(event.target as HTMLInputElement).files?.[0];if(!image)return;await run(async()=>{const form=new FormData();form.append('file',image);const result=await api<{marker:string}>(`courses/${props.courseId}/question-assets/`,'POST',form);(target as unknown as Record<string,string>)[field]+='\n'+result.marker;changed()})}
async function optionPicture(q:DraftQuestion,index:number,event:Event){const image=(event.target as HTMLInputElement).files?.[0];if(!image)return;await run(async()=>{const form=new FormData();form.append('file',image);const result=await api<{marker:string}>(`courses/${props.courseId}/question-assets/`,'POST',form);q.options[index]+='\n'+result.marker;changed()})}
function transfer(from:DraftGroup,qindex:number,event:Event){const target=source.value!.draft.groups[Number((event.target as HTMLSelectElement).value)];if(target&&target!==from){target.questions.push(from.questions.splice(qindex,1)[0]);changed()}}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
defineExpose({canLeave:mayLeave})
onMounted(async()=>{await run(()=>load());loading.value=false;window.addEventListener('beforeunload',beforeUnload);timer=setInterval(async()=>{now.value=Date.now();const s=source.value;if(!s||busy.value||!['queued','running'].includes(s.status))return;try{const result=await api<ExamSource>(`exam-sources/${s.id}/`);if(source.value?.id===s.id&&!dirty.value){source.value=result;if(result.status!==s.status){unitId.value=result.units[0]?.id||1;await load()}}}catch(e){error.value=e instanceof Error?e.message:'任务状态加载失败'}},2500)})
onUnmounted(()=>{if(timer)clearInterval(timer);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
<section class="exam-workspace" aria-label="试卷识别与整理">
<div class="section-head"><div><h3>试卷识别与整理</h3><p>上传原卷 → Agent 整理题目 → 校对入库 → 组卷设分</p></div><button type="button" class="secondary" :disabled="busy" @click="run(()=>load())">刷新任务列表</button></div>
<p v-if="loading" role="status">正在加载试卷…</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<form class="exam-upload" @submit.prevent="upload"><label>上传试卷 / 多页照片<input type="file" multiple accept=".txt,.png,.jpg,.jpeg,.webp,.docx,.pdf" :disabled="busy" @change="choose"></label><label>用手机拍摄试卷<input type="file" accept="image/*" capture="environment" :disabled="busy" @change="choose"></label><p v-if="uploadFiles.length">已选 {{uploadFiles.length}} 个文件：{{uploadFiles.map(f=>f.name).join('、')}}</p><button type="submit" class="primary" :disabled="busy||!file">{{busy?'处理中…':'上传并识别'}}</button><p>支持文字、图片、Word（DOCX）与 PDF。多张照片按选择顺序合为一份原卷，最多12页、合计20 MiB；PDF或Word单独上传。答案可留空，分值在组卷时设置。原卷仅所有者可见。</p></form>
<form class="paper-search" @submit.prevent="run(()=>load())"><label>查找试卷<input v-model="query" type="search" placeholder="输入试卷名称"></label><label><input v-model="showArchived" type="checkbox" @change="run(()=>load())">已归档</label><button class="secondary">查找</button></form>
<div class="exam-list"><p v-if="!loading&&!rows.length">还没有上传试卷。也可使用“管理题库”手工建题。</p><button v-for="row in rows" :key="row.id" type="button" class="secondary" :aria-pressed="source?.id===row.id" @click="select(row.id)">{{row.name}} · {{({queued:'排队中',running:'正在识别',ready:'待整理',failed:'识别失败',committed:'已入库'} as Record<string,string>)[row.status]||row.status}}</button><button v-if="next" class="secondary" :disabled="busy" @click="run(()=>load(next!))">更多试卷</button></div>
<section v-if="source" class="exam-source">
<div class="section-head paper-head"><button class="secondary" :disabled="busy" @click="closePaper">返回试卷列表</button><div><h3>{{source.name}}</h3><small>{{questionCount}} 道题 · {{dirty?'有未保存修改':'内容已保存'}} · {{source.status==='committed'?'已关联题库':'识别与整理'}}</small></div><button class="secondary" :disabled="busy" @click="run(()=>openProtected(source!.download_url))">下载原卷</button></div>
<p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<details class="paper-settings"><summary>试卷设置：重命名 / 归档</summary><div class="paper-management"><label>试卷名称<input v-model="paperName" maxlength="200" :disabled="!!source.archived_at"></label><button class="secondary" :disabled="busy||paperName===source.name||!!source.archived_at" @click="manage('rename')">重命名</button><button class="secondary" :disabled="busy||['queued','running'].includes(source.status)" @click="manage(source.archived_at?'restore':'archive')">{{source.archived_at?'恢复原卷':'归档原卷'}}</button></div></details><p v-if="source.archived_at" role="status">这份原卷已归档。恢复后可继续编辑，题库和历史考试均保留。</p>
<ol class="recognition-steps"><li :class="{complete:true}">1 · 原卷已保存</li><li :class="{complete:['ready','committed'].includes(source.status),active:['queued','running'].includes(source.status)}">2 · {{source.status==='queued'?'等待处理':source.status==='running'?'正在识别':source.status==='failed'?'识别未完成':'识别完成'}}</li><li :class="{active:source.status==='ready',complete:source.status==='committed'}">3 · 教师校对</li><li :class="{complete:source.status==='committed'}">4 · 加入题库</li></ol><p v-if="source.model" class="muted">识别模型：{{source.model}} · {{source.draft.groups?.reduce((n,g)=>n+g.questions.length,0)||0}} 道题</p><p v-if="source.error" class="error" role="alert">{{source.error}}</p>
<p v-if="['queued','running'].includes(source.status)" role="status">{{source.status==='queued'?'等待后台领取':'正在识别文字、图片和题组结构'}}。已上传 {{Math.floor(elapsed/60)}} 分 {{elapsed%60}} 秒，模型较忙时可能需要几分钟。可以离开后回来查看。</p>
<div class="forum-actions"><button v-if="source.status!=='committed'" type="button" class="secondary" :disabled="busy" @click="action('manual')">{{['queued','running'].includes(source.status)?'停止等待，改为人工整理':'人工整理'}}</button><button v-if="['ready','failed'].includes(source.status)" class="secondary" :disabled="busy||dirty" @click="action('retry')">重新识别</button><button type="button" class="secondary" :disabled="busy" @click="select(source.id)">重新读取已保存内容</button></div>
<div v-if="source.units.length" class="exam-columns">
<aside class="exam-original"><h4>原卷对照 · {{currentUnit?.label}}</h4><label>来源位置<select v-model="unitId"><option v-for="unit in source.units" :key="unit.id" :value="unit.id">{{unit.label}}</option></select></label><template v-if="currentUnit"><label>裁图插入位置<select aria-label="裁图插入位置" v-model="cropTarget" :disabled="busy"><option value="body">当前小题题干</option><option value="material">当前题组共享材料</option><option value="explanation">当前小题解析（答案公开前隐藏）</option></select></label><label>插入方式<select aria-label="插入方式" v-model="replaceMarker" :disabled="busy"><option value="">追加新图</option><option v-for="marker in cropMarkers" :key="marker" :value="marker">替换 {{marker}}</option></select></label><p>替换仅修改所选位置的图标记，其他题目与历史试卷不变；先核对预览再保存。</p><PaperImageCropper v-for="id in currentUnit.asset_ids" :key="id" :asset-id="id" :source-id="source.id" :revision="source.revision" :disabled="busy||!!source.archived_at||!source.draft.groups?.[selectedGroup]?.questions[selectedQuestion]" @insert="insertCrop"/><details :open="!currentUnit.asset_ids.length"><summary>原文提取结果</summary><QuestionContent :text="currentUnit.text"/></details></template><p>原卷仅教师可见；裁剪后的题图才会随题目提供给学生。</p></aside>
<div class="exam-editor">
<template v-if="source.status==='committed'"><h4>整卷编辑 · 已关联题库</h4><p>这里直接编辑整份试卷，保存后同步题库；历史答卷保持原样。</p><details><summary>原卷 → 题库索引（{{source.mapping.length}} 题）</summary><div v-for="(item,index) in source.mapping" :key="item.question_id" class="exam-index"><span>{{index+1}}. 题目 #{{item.question_id}} · 来源 {{item.source_units.join('、')}}</span><button class="secondary" @click="emit('editQuestion',item.question_id)">单独管理题目</button></div></details><button class="primary" :disabled="dirty||!!source.archived_at" @click="emit('assemble',source.mapping.map(m=>m.question_id))">按此原卷创建测验，设置分值</button></template>
<template v-if="['ready','failed','committed'].includes(source.status)&&source.draft.groups&&!source.archived_at">
<p role="status">{{dirty?'有未保存修改':'已读取保存版本'}} · 答案与解析可不填。移动或合并小题后，请检查共享材料。</p>
<div class="paper-toolbar"><strong>{{source.draft.groups.length}} 个题组 · {{questionCount}} 道题</strong><button class="secondary" :aria-pressed="previewMode" @click="previewMode=!previewMode">{{previewMode?'返回编辑':'预览整份试卷'}}</button><button class="primary" :disabled="busy||!dirty" @click="run(save)">{{source.status==='committed'?'保存并同步题库':'保存整理内容'}}</button></div>
<nav v-if="!previewMode" class="paper-outline" aria-label="试卷题目目录"><section v-for="(g,gi) in source.draft.groups" :key="gi"><button class="outline-group" :aria-current="selectedGroup===gi?'true':undefined" @click="focusQuestion(gi,0)">{{gi+1}}. {{g.title||'未命名题组'}} · {{g.questions.length}}题</button><div><button v-for="(q,qi) in g.questions" :key="qi" :class="{selected:selectedGroup===gi&&selectedQuestion===qi}" @click="focusQuestion(gi,qi)">{{qi+1}} · {{q.body.replace(/\{\{asset:\d+\}\}/g,'[图]').slice(0,24)||'新题目'}}</button></div></section></nav>
<section v-if="previewMode" class="paper-preview"><article v-for="(g,gi) in source.draft.groups" :key="gi"><h3>{{g.title}}</h3><QuestionContent :text="g.material"/><section v-for="(q,qi) in g.questions" :key="qi"><h4>{{qi+1}}. {{kinds[q.kind]}}</h4><QuestionContent :text="q.body"/><QuestionContent v-for="(o,oi) in q.options" :key="oi" :text="`${String.fromCharCode(65+oi)}. ${o}`"/></section></article></section>
<div v-show="!previewMode">
<article v-for="(group,gi) in source.draft.groups" v-show="selectedGroup===gi" :key="gi" class="exam-draft-group">
<div v-show="selectedGroup===gi">
<div class="forum-actions"><strong>题组 {{gi+1}}</strong><button class="secondary" :disabled="gi===0" @click="move(source.draft.groups,gi,-1)">上移题组</button><button class="secondary" :disabled="gi===source.draft.groups.length-1" @click="move(source.draft.groups,gi,1)">下移题组</button><button class="secondary" @click="removeGroup(gi)">移除题组</button></div>
<label>题组标题<input v-model="group.title" maxlength="200" @input="changed"></label><label>共享材料 / 文章 / 条件<textarea v-model="group.material" rows="7" maxlength="30000" @input="changed"></textarea></label><label>添加材料配图<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="picture(group,'material',$event)"></label><details><summary>材料预览</summary><QuestionContent :text="group.material"/></details>
<fieldset><legend>材料来源</legend><label v-for="unit in source.units" :key="unit.id"><input v-model="group.source_units" type="checkbox" :value="unit.id" @change="changed">{{unit.label}}</label></fieldset>
<article v-for="(q,qi) in group.questions" v-show="selectedQuestion===qi" :key="qi" class="exam-draft-question">
<div v-show="selectedQuestion===qi">
<div class="forum-actions"><strong>小题 {{qi+1}}</strong><button class="secondary" :disabled="qi===0" @click="move(group.questions,qi,-1)">上移</button><button class="secondary" :disabled="qi===group.questions.length-1" @click="move(group.questions,qi,1)">下移</button><button class="secondary" @click="removeQuestion(group,qi)">移除</button></div>
<label>移入其他题组<select :value="gi" @change="transfer(group,qi,$event)"><option v-for="(g,i) in source.draft.groups" :key="i" :value="i">{{i+1}}. {{g.title}}</option></select></label>
<label>题型<select v-model="q.kind" @change="setKind(q)"><option v-for="(name,value) in kinds" :key="value" :value="value">{{name}}</option></select></label>
<label>题干<textarea v-model="q.body" rows="4" maxlength="20000" @input="changed"></textarea></label><label>添加题干配图<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="picture(q,'body',$event)"></label>
<fieldset v-if="['single','multiple'].includes(q.kind)"><legend>选项与正确答案（可暂不选择）</legend><div v-for="(_,oi) in q.options" :key="oi" class="exam-option"><input :type="q.kind==='single'?'radio':'checkbox'" :name="`answer-${source.id}-${gi}-${qi}`" :checked="q.answer.values.includes(String(oi))" :aria-label="`正确选项 ${String.fromCharCode(65+oi)}`" @change="toggleAnswer(q,oi)"><label>{{String.fromCharCode(65+oi)}}<textarea v-model="q.options[oi]" rows="2" maxlength="2000" @input="changed"></textarea></label><label>选项配图<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="optionPicture(q,oi,$event)"></label><button class="secondary" :disabled="q.options.length<=2" @click="removeOption(q,oi)">移除选项</button></div><button class="secondary" :disabled="q.options.length>=10" @click="q.options.push('');changed()">添加选项</button><button class="secondary" @click="q.answer.values=[];changed()">清空答案</button></fieldset>
<label v-else-if="q.kind==='boolean'">答案（可不填）<select :value="q.answer.values[0]||''" @change="q.answer.values=($event.target as HTMLSelectElement).value?[($event.target as HTMLSelectElement).value]:[];changed()"><option value="">暂不填写</option><option value="true">正确</option><option value="false">错误</option></select></label>
<label v-else>参考答案 / {{q.kind==='blank'?'同一空的等价答案':'评分参考'}}（选填，每行一个）<textarea :value="q.answer.values.join('\n')" rows="3" @input="q.answer.values=($event.target as HTMLTextAreaElement).value.split('\n').filter(v=>v.trim());changed()"></textarea></label>
<label>解析（选填）<textarea v-model="q.explanation" rows="3" @input="changed"></textarea></label><label>添加解析配图<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="picture(q,'explanation',$event)"></label>
<fieldset><legend>本题来源</legend><label v-for="unit in source.units" :key="unit.id"><input v-model="q.source_units" type="checkbox" :value="unit.id" @change="changed">{{unit.label}}</label></fieldset>
<details><summary>题目预览</summary><QuestionContent :text="q.body"/><QuestionContent v-for="(o,i) in q.options" :key="i" :text="`${String.fromCharCode(65+i)}. ${o}`"/><QuestionContent :text="q.explanation"/></details>
</div></article><button class="secondary" @click="addQuestion(group)">添加小题</button>
</div></article>
<div class="forum-actions"><button class="secondary" @click="addGroup">添加题组 / 拆分材料</button><button class="secondary" :disabled="busy||!dirty" @click="run(save)">保存整理内容</button></div>
</div>
<template v-if="source.status!=='committed'"><label class="exam-confirm"><input v-model="confirmed" type="checkbox">我已核对题干、材料、配图和来源；答案可暂缺，后续仍可编辑。</label><button class="primary" :disabled="busy||!confirmed" @click="action('commit')">确认加入我的题库</button></template>
<details v-if="source.history?.length"><summary>保存记录（当前版本 {{source.revision}}）</summary><p v-for="h in source.history" :key="h.revision">版本 {{h.revision}} · {{new Date(h.created_at).toLocaleString()}}</p></details>
</template>
</div></div>
</section></section>
</template>
